/* Backbone CSS for Resume Template 1 */

/* Basic */

#resume-preview [data-scope="vue-smart-pages"][data-part="page"] {
  background-color: white;
  color: black;
  text-align: justify;
  -moz-hyphens: auto;
  -ms-hyphens: auto;
  -webkit-hyphens: auto;
  hyphens: auto;
}

#resume-preview p,
#resume-preview li,
#resume-preview dl {
  margin: 0;
}

/* Headings */

#resume-preview h1,
#resume-preview h2,
#resume-preview h3 {
  font-weight: bold;
}

#resume-preview h1 {
  font-size: 2.13em;
}

#resume-preview h2,
#resume-preview h3 {
  margin-bottom: 5px;
  font-size: 1.2em;
}

#resume-preview h2 {
  border-bottom-style: solid;
  border-bottom-width: 1px;
}

/* Lists */

#resume-preview ul,
#resume-preview ol {
  padding-left: 1.5em;
  margin: 0.2em 0;
}

#resume-preview ul {
  list-style-type: circle;
}

#resume-preview ol {
  list-style-type: decimal;
}

/* Definition Lists */

#resume-preview dl {
  display: flex;
}

#resume-preview dl dt,
#resume-preview dl dd:not(:last-child) {
  flex: 1;
}

/* Tex */

#resume-preview :not(span.katex-display) > span.katex {
  font-size: 1em !important;
}

/* SVG & Images */

#resume-preview svg.iconify {
  vertical-align: -0.2em;
}

#resume-preview img {
  max-width: 100%;
}

/* Photo */

#resume-preview [data-scope="vue-smart-pages"][data-part="page"] {
  position: relative;
}

#resume-preview .resume-photo-anchor {
  height: 0;
  overflow: visible;
}

#resume-preview .resume-photo {
  position: absolute;
  top: 0px;
  right: 45px;
  width: 78px;
  height: 105px;
  object-fit: cover;
  border-radius: 4px;
  border: 1px solid rgba(0, 0, 0, 0.18);
  background-color: white;
}

/* 教育背景（照片锚点后的首个标题）相对默认段间距下移 10px */

#resume-preview .resume-photo-anchor + h2 {
  margin-top: 13px;
}

/* Company Header（公司与项目行区分样式） */

#resume-preview .company-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 8px;
  row-gap: 2px;
  margin: 4px 0 6px;
  padding: 5px 8px;
  background-color: rgba(55, 123, 181, 0.07);
  border-left: 3px solid #377bb5;
}

#resume-preview .company-name {
  font-size: 1.18em;
  font-weight: bold;
  color: #377bb5;
}

#resume-preview .company-meta {
  color: #555;
}

#resume-preview .company-date {
  margin-left: auto;
  color: #666;
  font-size: 0.92em;
}

/* Project Title（项目/经历标题行，与下方正文拉开区分度） */

#resume-preview .project-title {
  color: #377bb5;
  font-size: 1.15em;
}

/* Header */

#resume-preview .resume-header {
  text-align: center;
}

#resume-preview .resume-header h1 {
  text-align: center;
  line-height: 1;
  margin: 0 0 8px; /* 去掉浏览器默认 h1 上边距，减少顶部留白 */
}

#resume-preview .resume-header-item:not(.no-separator)::after {
  content: " | ";
}

/* Citations */

#resume-preview [data-scope="cross-ref"][data-part="definitions"] {
  padding-left: 1.2em;
}

#resume-preview [data-scope="cross-ref"][data-part="definition"] p {
  margin-left: 0.5em;
}

#resume-preview [data-scope="cross-ref"][data-part="definition"]::marker {
  content: attr(data-label);
}

#resume-preview [data-scope="cross-ref"][data-part="reference"] {
  font-size: 100%;
  top: 0;
}

/* Dark & print mode */
/* You might want to comment out the following lines if you change the background or text color. */

.dark #resume-preview [data-scope="vue-smart-pages"][data-part="page"] {
  background-color: hsl(213, 12%, 15%);
  color: hsl(216, 12%, 84%);
}

@media print {
  .dark #resume-preview [data-scope="vue-smart-pages"][data-part="page"] {
    background-color: white;
    color: black;
  }
}
